-- Framework migration 130: configurable domain health evaluation cadence.
--
-- The historical 040 migration created CONTROL.EVALUATE_DOMAIN_HEALTH_TASK with a fixed
-- one-minute schedule. 040 is released and immutable. This migration does NOT silently
-- retune that task. Instead it adds a narrow audit contract used by explicit, reviewed
-- health-cadence operations generated by `esf health-cadence-sql`.
--
-- Actual Task state/schedule should be verified with SHOW TASKS. This table records only
-- Framework-generated change attempts; it is not a runtime scheduler or source of truth
-- for out-of-band Task edits.

CREATE TABLE IF NOT EXISTS CONTROL.HEALTH_EVALUATION_CHANGE (
    OPERATION_ID VARCHAR NOT NULL,
    TASK_NAME VARCHAR NOT NULL,
    INTERVAL_SECONDS NUMBER(38,0) NOT NULL,
    REQUESTED_FINAL_STATE VARCHAR NOT NULL,
    REASON VARCHAR NOT NULL,
    STATUS VARCHAR NOT NULL,
    STARTED_AT TIMESTAMP_LTZ NOT NULL,
    COMPLETED_AT TIMESTAMP_LTZ,
    OPERATOR VARCHAR,
    CREATED_AT TIMESTAMP_LTZ DEFAULT CURRENT_TIMESTAMP()
);

CREATE VIEW IF NOT EXISTS CONTROL.HEALTH_EVALUATION_CONFIG_V AS
SELECT
    OPERATION_ID,
    TASK_NAME,
    INTERVAL_SECONDS,
    REQUESTED_FINAL_STATE,
    REASON,
    OPERATOR,
    COMPLETED_AT AS RECORDED_AT
FROM CONTROL.HEALTH_EVALUATION_CHANGE
WHERE STATUS = 'SUCCEEDED'
QUALIFY ROW_NUMBER() OVER (
    ORDER BY COMPLETED_AT DESC, CREATED_AT DESC, OPERATION_ID DESC
) = 1;

-- No ALTER TASK occurs in this migration. An existing domain keeps its current schedule
-- until an engineer reviews and explicitly executes a generated cadence operation.
